"""Contract test for workspaces generated by ``scripts/new-fit``."""

import shutil
import tempfile
from pathlib import Path

from tests.workspace_contracts import (
    NEW_FIT,
    WorkspaceContractTestCase,
    install_fake_runtime,
)


class FitWorkspaceTests(WorkspaceContractTestCase):
    def test_new_fit_workspace_submits_and_runs_with_valid_contract(self):
        with tempfile.TemporaryDirectory() as tmp:
            mini_repo = Path(tmp) / "repo"
            (mini_repo / "scripts").mkdir(parents=True)
            (mini_repo / "datasets" / "nested").mkdir(parents=True)
            shutil.copy2(NEW_FIT, mini_repo / "scripts" / "new-fit")

            setup_env, environment, condor_log = install_fake_runtime(
                mini_repo,
                setup_env=mini_repo / "scripts" / "setup-env.sh",
            )
            self.assertTrue(setup_env.is_file())

            template = mini_repo / "input-template"
            template.mkdir()
            (template / "steering.txt").write_text(
                "&InFiles\n"
                "  NInputFiles = 1\n"
                "  InputFileNames = 'legacy/path/toy.dat'\n"
                "&End\n"
            )
            (template / "parameters.yaml").write_text(
                "Minimizer: MINUIT\n"
                "Parameters:\n"
                "  Bg: [0.0, 0.1]\n"
                "OutputDirectory: \"obsolete\"\n"
            )
            (template / "constants.yaml").write_text("constants: test\n")
            (template / "unpolarised.wgt").write_text("toy weight\n")
            dataset_content = "toy dataset\n"
            (mini_repo / "datasets" / "nested" / "toy.dat").write_text(
                dataset_content
            )

            self.run_checked(
                ["bash", mini_repo / "scripts" / "new-fit", "contract/manual", template],
                cwd=mini_repo,
                env=environment,
            )

            fit_dir = mini_repo / "runs" / "fits" / "contract" / "manual"
            config_dir = fit_dir / "config"
            self.assertEqual((config_dir / "toy.dat").read_text(), dataset_content)
            steering = (config_dir / "steering.txt").read_text()
            self.assertIn("'toy.dat'", steering)
            self.assertNotIn("legacy/path", steering)
            self.assertIn(
                'OutputDirectory: "__SET_AT_RUNTIME__"',
                (config_dir / "parameters.yaml").read_text(),
            )

            submit_script = fit_dir / "condor" / "submit.sh"
            self.assert_shell_syntax(submit_script)
            self.run_checked(["bash", submit_script], cwd=mini_repo, env=environment)

            worker = fit_dir / "condor" / "run_fit.sh"
            descriptor = fit_dir / "condor" / "job.sub"
            self.assert_shell_syntax(worker)
            self.assertEqual(
                condor_log.read_text().splitlines(),
                [str(descriptor.resolve())],
            )

            self.run_checked(["bash", worker], cwd=config_dir, env=environment)
            self.assert_worker_outputs(fit_dir)
